      "path": "e2e/run-real-session.mjs",
      "content": "#!/usr/bin/env node\n/**\n * oh-my-dsh REAL session smoke: boots the full DSH agent stack (real DeepSeek\n * adapter, bash/fs/subagent tools) PLUS every oh-my-dsh plugin, runs one real\n * agent turn, and proves (a) the agent responds and (b) an oh-my-dsh plugin\n * tool actually executes against the live registry.\n *\n * Usage: DEEPSEEK_API_KEY=… node --import tsx e2e/run-real-session.mjs <dsh-src> [config]\n */\n\nimport { createRequire } from 'node:module'\nconst require = createRequire(import.meta.url)\nconst dshSrc = process.argv[2] ?? process.cwd()\nconst configPath = process.argv[3] ?? 'examples/headless-agent/cordis.real-session.yml'\n\nconst { boot } = require(require.resolve('@deepseek-ai/dsh-app-boot', { paths: [dshSrc] }))\nconst { createUserMessage } = require(require.resolve('@deepseek-ai/dsh-llm', { paths: [dshSrc] }))\n\nlet failures = 0\nconst checks = []\nfunction check(name, ok, detail = '') {\n  checks.push({ name, ok })\n  console.log(`  ${ok ? '✓' : '✗'} ${name}${detail ? ` — ${detail}` : ''}`)\n  if (!ok) failures++\n}\n\n/** Drive one task through the single root agent, returning its final text. */\nasync function driveTurn(ctx, task) {\n  const agents = ctx.get('agents')?.roots?.() ?? []\n  const agent = agents[0]\n  if (!agent || agents.length !== 1) throw new Error(`expected one root agent, found ${agents.length}`)\n  await agent.whenIdle()\n  const message = createUserMessage({\n    content: [{ type: 'text', text: task }],\n    source: { kind: 'user' },\n  })\n  let output = ''\n  const dispose = ctx.on('session/event', (session, event) => {\n    if (session !== agent.session) return\n    if (event.type === 'assistant/message') {\n      const text = (event.data.message.content ?? [])\n        .filter(b => b.type === 'text')\n        .map(b => b.text)\n        .join('')\n      if (text.trim()) output = text\n    }\n  })\n  try {\n    agent.followup(message)\n    await agent.whenIdle()\n  } finally {\n    dispose()\n  }\n  await ctx.sessions?.flush?.(agent.session)\n  return output\n}\n\ntry {\n  const ctx = await boot('oh-my-dsh-real-session', configPath)\n  try {\n    // (a) Expected plugin tools are registered against the live registry.\n    const expected = ['deep_research', 'tower', 'ohmy_hello', 'rc_report']\n    for (const tool of expected) {\n      check(`tool registered: ${tool}`, ctx.tools.get(tool) !== undefined)\n    }\n\n    // (b) Execute one oh-my-dsh plugin tool directly (in-memory, no LLM).\n    try {\n      const rcReport = ctx.tools.get('rc_report')\n      const result = await rcReport.execute({}, { name: 'rc_report', arguments: {}, signal: new AbortController().signal })\n      check('plugin tool executes (rc_report)', typeof result === 'string' && result.includes('entries'), String(result))\n    } catch (e) {\n      check('plugin tool executes (rc_report)', false, e?.message)\n    }\n\n    // (c) One real agent turn through the DeepSeek model.\n    const output = await driveTurn(ctx, 'Reply with exactly: PLUGINS-OK')\n    console.log(`  · agent output: ${output.slice(0, 200).replace(/\\n/g, ' ')}`)\n    check('real agent turn completed', output.length > 0, `${output.length} chars`)\n  } finally {\n    try { await ctx.dispose?.() } catch { /* best-effort */ }\n  }\n} catch (error) {\n  failures++\n  console.error('BOOT/RUN FAILED:', error?.message ?? error)\n  if (error?.stack) console.error(error.stack.split('\\n').slice(0, 6).join('\\n'))\n}\n\nconsole.log(`\\n${checks.length - failures}/${checks.length} checks passed`)\nprocess.exit(failures === 0 ? 0 : 1)\n"
    },
