    {
      "path": "plugins/deep-research/src/index.ts",
      "content": "/**\n * GAP-1354: deep research — autonomous multi-step web research.\n *\n * Claude Code / Oh-my-pi both ship an autonomous \"deep research\" mode: take a\n * compound question, decompose it into sub-questions, search and fetch sources\n * in parallel, and synthesize a cited report. This plugin exposes that\n * capability to the DSH model as a single `deep_research` tool, wired through\n * the documented seams:\n *\n *   - `ctx.web.search()` / `ctx.web.fetch()` gather sources (the portable\n *     citation shape, not any one provider's wire format),\n *   - `ctx.llm.stream()` decomposes the question and synthesizes the report\n *     when a `provider` + `model` are configured,\n *   - both degrade gracefully: without `web` the tool reports no sources;\n *     without `llm` (or before a model is configured) a deterministic\n *     template report is produced from the gathered sources.\n *\n * Pure helpers are exported for hermetic tests; no real API key is required.\n *\n * @module @oh-my-dsh/deep-research\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\n\nexport const name = 'oh-my-dsh-deep-research'\n\n/** Services required before this plugin can register. */\nexport const inject = ['tools']\n\n/** Plugin configuration (all knobs are cordis.yml-configurable). */\nexport interface Config {\n  /** LLM provider route for decomposition/synthesis (optional). */\n  provider?: string\n  /** LLM model for decomposition/synthesis (required for the LLM path). */\n  model?: string\n  /** Max sub-questions when decomposing (default 4, clamped to 1..8). */\n  maxSubquestions?: number\n  /** Max sources gathered per sub-question (default 4). */\n  maxSourcesPerQuestion?: number\n  /** Max chars of the final report before truncation (default 8000). */\n  maxReportChars?: number\n  /** Whether to fetch full bodies of the top sources (default false). */\n  fetchBodies?: boolean\n}\n\n/** One citeable source (portable subset of DSH's WebSearchSource). */\nexport interface ResearchSource {\n  url: string\n  title?: string\n  snippet?: string\n}\n\n/** The completed research outcome. */\nexport interface ResearchReport {\n  report: string\n  sources: ResearchSource[]\n  questions: string[]\n}\n\n/** Clamp a finite number into [min, max]. */\nfunction clamp(value: number, min: number, max: number): number {\n  if (!Number.isFinite(value)) return min\n  return Math.min(max, Math.max(min, Math.floor(value)))\n}\n\n/**\n * Fallback decomposition: split a compound question into sub-questions on\n * question marks, semicolons and newlines. The LLM path overrides this when a\n * model is configured.\n */\nexport function buildSubquestions(question: string, breadth: number): string[] {\n  const trimmed = question.trim()\n  if (trimmed === '') return []\n  const parts = trimmed\n    .split(/\\?|\\n|;/)\n    .map(s => s.trim().replace(/^[-*\\d.)]+\\s*/, ''))\n    .filter(s => s.length > 0)\n  const unique: string[] = []\n  for (const p of parts) {\n    const q = p.endsWith('?') ? p : `${p}?`\n    if (!unique.includes(q)) unique.push(q)\n    if (unique.length >= breadth) break\n  }\n  return unique\n}\n\n/** Deduplicate sources by URL, preserving first-seen order. */\nexport function dedupeSources(sources: readonly ResearchSource[]): ResearchSource[] {\n  const seen = new Set<string>()\n  const out: ResearchSource[] = []\n  for (const s of sources) {\n    if (!s || typeof s.url !== 'string' || s.url === '') continue\n    if (seen.has(s.url)) continue\n    seen.add(s.url)\n    out.push(s)\n  }\n  return out\n}\n\n/** One LLM stream chunk (structural subset). */\nexport interface StreamChunkLike {\n  type?: string\n  text?: string\n}\n\n/** Collect `text-delta` chunks into a single string. */\nexport async function collectText(chunks: AsyncIterable<StreamChunkLike>): Promise<string> {\n  let out = ''\n  for await (const chunk of chunks) {\n    if (chunk && chunk.type === 'text-delta' && typeof chunk.text === 'string') out += chunk.text\n  }\n  return out\n}\n\n/** Extract a bounded text excerpt from a fetched body. */\nexport function extractExcerpt(\n  body: { kind: string; content: string } | undefined,\n  maxChars: number,\n): string {\n  if (!body || typeof body.content !== 'string') return ''\n  const text = body.kind === 'html' ? body.content.replace(/<[^>]+>/g, ' ').replace(/\\s+/g, ' ').trim() : body.content\n  return text.length > maxChars ? `${text.slice(0, maxChars)}…` : text\n}\n\n/**\n * Fallback synthesis: a deterministic cited report from the gathered sources.\n * Produced when the LLM path is unavailable; replaced by the LLM synthesis\n * when a model is configured and sources were gathered.\n */\nexport function buildReportTemplate(\n  question: string,\n  questions: readonly string[],\n  sources: readonly ResearchSource[],\n  maxChars: number,\n): string {\n  const lines: string[] = [`# Deep Research: ${question}`, '']\n  if (questions.length > 0) {\n    lines.push('## Sub-questions', ...questions.map(q => `- ${q}`), '')\n  }\n  lines.push(`## Findings (${sources.length} source${sources.length === 1 ? '' : 's'})`, '')\n  if (sources.length === 0) {\n    lines.push('(no sources gathered — web search may be unavailable)', '')\n  } else {\n    sources.forEach((s, i) => {\n      lines.push(`[${i + 1}] ${s.title ?? s.url}`, `    ${s.url}`)\n      if (s.snippet) lines.push(`    ${s.snippet.slice(0, 240)}`)\n      lines.push('')\n    })\n  }\n  const text = lines.join('\\n')\n  return text.length > maxChars ? `${text.slice(0, maxChars)}…[truncated]` : text\n}\n\n/** Structural mirror of the DSH web capability seam. */\nexport interface WebLike {\n  search?(request: { query: string; maxResults?: number }, signal?: unknown): Promise<{\n    content?: string\n    sources?: readonly ResearchSource[]\n  }>\n  fetch?(request: { url: string }, signal?: unknown): Promise<{ body?: { kind: string; content: string } }>\n}\n\n/** Structural mirror of the DSH llm streaming seam. */\nexport interface LlmLike {\n  stream?(options: {\n    provider?: string\n    model?: string\n    system?: string\n    messages?: unknown[]\n    signal?: unknown\n  }): AsyncIterable<StreamChunkLike>\n}\n\n/** Structural mirror of the DSH tools registration contract. */\nexport interface ToolsService {\n  register(def: { name: string } & Record<string, unknown>): () => void\n}\n\n/** Ask the LLM to decompose a question into up to `breadth` sub-questions. */\nasync function decomposeViaLlm(\n  llm: LlmLike,\n  question: string,\n  breadth: number,\n  config: Config,\n): Promise<string[]> {\n  const chunks = llm.stream?.({\n    provider: config.provider,\n    model: config.model,\n    system: 'You decompose a research question into focused sub-questions. Return one sub-question per line, no numbering.',\n    messages: [{ role: 'user', content: `Decompose into up to ${breadth} sub-questions:\\n${question}` }],\n  })\n  if (!chunks) return []\n  const text = await collectText(chunks)\n  return text\n    .split('\\n')\n    .map(s => s.trim().replace(/^[-*\\d.)]+\\s*/, ''))\n    .filter(s => s.length > 0)\n    .map(s => (s.endsWith('?') ? s : `${s}?`))\n    .slice(0, breadth)\n}\n\n/** Ask the LLM to synthesize a cited report from the gathered sources. */\nasync function synthesizeViaLlm(\n  llm: LlmLike,\n  question: string,\n  sources: readonly ResearchSource[],\n  config: Config,\n): Promise<string> {\n  const evidence = sources\n    .map((s, i) => `[${i + 1}] ${s.title ?? s.url}\\n${s.url}\\n${s.snippet ?? ''}`)\n    .join('\\n\\n')\n  const chunks = llm.stream?.({\n    provider: config.provider,\n    model: config.model,\n    system: 'You are a research analyst. Write a concise, well-cited report from the provided sources. Cite sources by their [n] number.',\n    messages: [{ role: 'user', content: `Question: ${question}\\n\\nSources:\\n${evidence}\\n\\nWrite the report:` }],\n  })\n  if (!chunks) return ''\n  return collectText(chunks)\n}\n\nexport function apply(ctx: Context, config: Config = {}) {\n  ctx.effect(() => {\n    const tools = ctx.get('tools') as ToolsService\n    const web = ctx.get('web') as WebLike | undefined\n    const llm = ctx.get('llm') as LlmLike | undefined\n    const disposers: (() => void)[] = []\n\n    disposers.push(tools.register({\n      name: 'deep_research',\n      description: 'Autonomous multi-step web research: decompose a question, search/fetch sources in parallel, and synthesize a cited report.',\n      parameters: {\n        type: 'object',\n        properties: {\n          question: { type: 'string', description: 'The research question to investigate.' },\n          breadth: { type: 'number', description: 'Number of parallel sub-questions (default 4).' },\n        },\n        required: ['question'],\n      },\n      output: {\n        schema: {\n          type: 'object',\n          properties: {\n            report: { type: 'string' },\n            sources: {\n              type: 'array',\n              items: {\n                type: 'object',\n                properties: {\n                  url: { type: 'string' },\n                  title: { type: 'string' },\n                  snippet: { type: 'string' },\n                },\n                required: ['url'],\n              },\n            },\n            questions: { type: 'array', items: { type: 'string' } },\n          },\n          required: ['report', 'sources', 'questions'],\n        },\n        render: (_args: unknown, value: unknown) => {\n          const v = value as ResearchReport\n          const srcLines = v.sources.length > 0\n            ? v.sources.map(s => `- ${s.title ?? s.url}: ${s.url}`).join('\\n')\n            : '(no sources)'\n          return [{ type: 'text', text: `${v.report}\\n\\n## Sources\\n${srcLines}` }]\n        },\n      },\n      async execute(args: unknown): Promise<ResearchReport> {\n        const { question, breadth } = args as { question?: string; breadth?: number }\n        if (typeof question !== 'string' || question.trim() === '') {\n          throw new Error('deep_research: question is required')\n        }\n        const b = clamp(breadth ?? config.maxSubquestions ?? 4, 1, 8)\n        const maxSources = clamp(config.maxSourcesPerQuestion ?? 4, 1, 20)\n        const maxChars = clamp(config.maxReportChars ?? 8000, 500, 100_000)\n\n        // 1) Decompose: LLM when configured, else the deterministic heuristic.\n        let questions = buildSubquestions(question, b)\n        if (llm?.stream && config.model) {\n          try {\n            const generated = await decomposeViaLlm(llm, question, b, config)\n            if (generated.length > 0) questions = generated\n          } catch {\n            /* keep heuristic decomposition */\n          }\n        }\n\n        // 2) Research: parallel search per sub-question (skip sources already gathered).\n        const gathered: ResearchSource[] = []\n        if (web?.search) {\n          const batches = await Promise.all(questions.map(async q => {\n            try {\n              const result = await web.search?.({ query: q, maxResults: maxSources })\n              return result?.sources ?? []\n            } catch {\n              return []\n            }\n          }))\n          for (const batch of batches) gathered.push(...batch)\n        }\n        // Optional deep read of the top sources.\n        if (web?.fetch && config.fetchBodies === true) {\n          const top = dedupeSources(gathered).slice(0, maxSources)\n          const excerpts = await Promise.all(top.map(async s => {\n            try {\n              const result = await web.fetch?.({ url: s.url })\n              return { ...s, snippet: extractExcerpt(result?.body, 600) || s.snippet }\n            } catch {\n              return s\n            }\n          }))\n          gathered.length = 0\n          gathered.push(...excerpts)\n        }\n        const sources = dedupeSources(gathered).slice(0, maxSources * questions.length)\n\n        // 3) Synthesize: LLM when configured and sources exist, else the template.\n        let report = buildReportTemplate(question, questions, sources, maxChars)\n        if (llm?.stream && config.model && sources.length > 0) {\n          try {\n            const text = await synthesizeViaLlm(llm, question, sources, config)\n            if (text.trim().length > 0) report = text.slice(0, maxChars)\n          } catch {\n            /* keep template report */\n          }\n        }\n\n        return { report, sources, questions }\n      },\n    }))\n\n    return () => {\n      for (const dispose of disposers.reverse()) dispose()\n    }\n  })\n}\n"
    },
