      "path": "plugins/secret-scanner/src/index.ts",
      "content": "/**\n * Round-2 GAP-0308: pre-write secret scanning as a monotonic ToolGuard.\n *\n * A ToolGuard returns a rejection reason string or undefined (allow); guards\n * have no allow result, so a later listener cannot flip a denial back —\n * exactly the monotonic semantics secret scanning needs. This plugin:\n *\n *   - scans the *arguments* of write-class tools (write/edit/apply_patch)\n *     for common secret patterns (API keys, tokens, private keys),\n *   - registers as a guard, so the pipeline denies the call before any\n *     filesystem mutation,\n *   - never sees file contents it did not receive in args (no scan of\n *     existing files — that is a separate audit surface).\n *\n * Pure matcher; testable without the registry.\n *\n * @module @oh-my-dsh/secret-scanner\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\n\nexport const name = 'oh-my-dsh-secret-scanner'\n\n/** Services required before this plugin can register. */\nexport const inject = ['tools']\n\n/** Plugin configuration. */\nexport interface Config {\n  /** Tool names treated as write-class (scanned). */\n  writeTools?: string[]\n  /** Extra regex patterns (strings compiled to RegExp). */\n  extraPatterns?: string[]\n  /** Enable scanning; default true. */\n  enabled?: boolean\n}\n\n/** Default secret patterns (conservative, low false-positive). */\nexport const DEFAULT_PATTERNS: readonly RegExp[] = [\n  /\\b(?:sk|pk|ghp|gho|ghs|xoxb|xoxp)-[A-Za-z0-9_-]{16,}\\b/,\n  /\\bAKIA[0-9A-Z]{16}\\b/,                       // AWS access key id\n  /-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----/,\n  /\\b(?:api[_-]?key|secret|token|password)\\s*[:=]\\s*['\"][^'\"]{12,}['\"]/i,\n]\n\n/** Scan text for secret patterns; returns matched pattern descriptions. */\nexport function scanSecrets(\n  text: string,\n  patterns: readonly RegExp[] = DEFAULT_PATTERNS,\n): string[] {\n  const found: string[] = []\n  for (const pattern of patterns) {\n    if (pattern.test(text)) found.push(pattern.source)\n  }\n  return found\n}\n\n/** Scan a tool call's serialized arguments; returns matched patterns. */\nexport function scanToolArguments(\n  toolName: string,\n  args: unknown,\n  writeTools: readonly string[],\n  patterns: readonly RegExp[] = DEFAULT_PATTERNS,\n): string[] {\n  if (!writeTools.includes(toolName)) return []\n  let text: string\n  try {\n    text = JSON.stringify(args)\n  } catch {\n    return []\n  }\n  return scanSecrets(text, patterns)\n}\n\n/** Structural mirror of the DSH tools registry guard registration. */\nexport interface ToolsService {\n  register(def: { name: string } & Record<string, unknown>): () => void\n  guard?(guard: (execution: { name: string; arguments: unknown }) => string | undefined): () => void\n}\n\nexport function apply(ctx: Context, config: Config = {}) {\n  ctx.effect(() => {\n    const tools = ctx.get('tools') as ToolsService\n    const writeTools = config.writeTools ?? ['write', 'edit', 'apply_patch', 'str_replace_editor']\n    const patterns = [...DEFAULT_PATTERNS, ...(config.extraPatterns ?? []).map(p => new RegExp(p))]\n    const disposers: (() => void)[] = []\n\n    const guard = (execution: { name: string; arguments: unknown }): string | undefined => {\n      if (config.enabled === false) return undefined\n      const found = scanToolArguments(execution.name, execution.arguments, writeTools, patterns)\n      if (found.length > 0) {\n        return `secret-scan: potential secret written by ${execution.name} (patterns: ${found.join(', ')})`\n      }\n      return undefined\n    }\n\n    if (tools && typeof tools.guard === 'function') {\n      disposers.push(tools.guard(guard))\n    }\n\n    return () => {\n      for (const dispose of disposers.reverse()) dispose()\n    }\n  })\n}\n"
    },
