      "path": "plugins/tower/src/index.ts",
      "content": "/**\n * GAP-1355: tower — multi-agent team orchestration with conflict coordination.\n *\n * kimi-code's `/tower` command (MoonshotAI/kimi-code#2633) dispatches multiple\n * instructions to a team of workers that iterate one repo concurrently, with a\n * \"tower\" coordinating conflicts, assigning a reviewer, and merging results.\n * The coordination is out-of-order: every worker sees the full team brief, so\n * they avoid stepping on each other (M1 tells M2 it owns the README; M4 is\n * only scheduled after M3's output is known). This plugin ports that model to\n * DSH over the documented subagent seam:\n *\n *   - `ctx.subagents.start()` runs one worker per instruction in parallel,\n *   - each worker receives the shared team brief plus its own instruction,\n *   - a reviewer (primary model) re-reads the workers' outputs and flags\n *     conflicts/duplication,\n *   - the tool returns the plan, per-worker summaries, and the review.\n *\n * Pure helpers are exported for hermetic tests; the subagent seam is a\n * structural mirror so tests stub it without a running agent.\n *\n * @module @oh-my-dsh/tower\n */\n\nimport type { Context } from '@deepseek-ai/cordis'\n\nexport const name = 'oh-my-dsh-tower'\n\n/** Services required before this plugin can register. */\nexport const inject = ['tools']\n\n/** Plugin configuration (all knobs are cordis.yml-configurable). */\nexport interface Config {\n  /** Subagent provider name to run workers (default 'spawn'). */\n  provider?: string\n  /** Max parallel workers (default 8, clamped to 1..16). */\n  maxWorkers?: number\n  /** Whether to run the reviewer pass (default true). */\n  review?: boolean\n  /** Re-dispatch workers once more with the review feedback (default false). */\n  revisit?: boolean\n  /** Secondary model for workers (the reviewer stays on the primary model). */\n  secondaryModel?: { provider: string; model: string; maxTokens?: number }\n  /** JSON schema for workers' structured output (collected as `structured`). */\n  outputSchema?: { type: string; properties?: Record<string, unknown>; required?: string[] }\n}\n\n/** One instruction dispatched to a worker. */\nexport interface TowerInstruction {\n  /** The instruction text. */\n  instruction: string\n}\n\n/** One worker's terminal summary. */\nexport interface TowerWorkerResult {\n  instruction: string\n  summary: string\n  stopReason: string\n  structured?: unknown\n}\n\n/** The completed tower run. */\nexport interface TowerResult {\n  plan: string[]\n  workers: TowerWorkerResult[]\n  review: string\n  cleanup: string[]\n}\n\n/** Clamp a finite number into [min, max]. */\nfunction clamp(value: number, min: number, max: number): number {\n  if (!Number.isFinite(value)) return min\n  return Math.min(max, Math.max(min, Math.floor(value)))\n}\n\n/**\n * The shared team brief every worker receives: the full instruction set plus\n * an index-hinted ownership rule so workers avoid editing each other's files.\n */\nexport function buildTeamBrief(instructions: readonly string[]): string {\n  const rows = instructions.map((ins, i) => `  W${i + 1}: ${ins}`)\n  return [\n    'You are one worker on a team of agents working on the SAME repository concurrently.',\n    'Team plan:',\n    ...rows,\n    '',\n    'Coordination rules:',\n    '- Work only on your own instruction; do not edit files another worker owns.',\n    '- If two instructions touch the same file, the earlier worker (W1) owns it; others read it and adapt.',\n    '- Report what you changed and any conflict you noticed with another worker.',\n  ].join('\\n')\n}\n\n/** Build one worker's prompt from the brief + its instruction. */\nexport function buildWorkerPrompt(brief: string, instruction: string, index: number): string {\n  return [\n    brief,\n    '',\n    `Your task (W${index + 1}): ${instruction}`,\n    '',\n    'Complete the task, then summarize: what you changed, and any conflict with another worker.',\n  ].join('\\n')\n}\n\n/** Build the reviewer's prompt from the brief + collected worker outputs. */\nexport function buildReviewerPrompt(brief: string, results: readonly TowerWorkerResult[]): string {\n  const rows = results.map((r, i) => `  W${i + 1}: ${r.summary}`)\n  return [\n    brief,\n    '',\n    'You are the team reviewer (the tower). Re-read the workers\\' outputs and produce a review:',\n    '- List any conflict or duplicated work between workers.',\n    '- Say which changes need follow-up and why.',\n    'Worker outputs:',\n    ...rows,\n  ].join('\\n')\n}\n/** Build one worker's revisit prompt (original task + the team review feedback). */\nexport function buildRevisitPrompt(brief: string, instruction: string, index: number, review: string): string {\n  return [\n    buildWorkerPrompt(brief, instruction, index),\n    '',\n    'Team review feedback:',\n    review,\n    '',\n    'Address the feedback and re-submit your summary.',\n  ].join('\\n')\n}\n\n/** Extract follow-up/revert items from the review text (pure). */\nexport function parseCleanup(review: string): string[] {\n  return review\n    .split('\\n')\n    .map(line => line.trim())\n    .filter(line => line.startsWith('- ') || line.startsWith('* '))\n    .map(line => line.replace(/^[-*]\\s+/, ''))\n    .filter(line => /revert|follow.?up|conflict|duplicat|clean|remove|fix/i.test(line))\n}\n\n/** Extract plain text from a subagent's output content blocks. */\nexport function extractText(output: readonly { type: string; text?: string }[] | undefined): string {\n  if (!output) return ''\n  return output\n    .map(block => (block && block.type === 'text' && typeof block.text === 'string' ? block.text : ''))\n    .filter(Boolean)\n    .join('\\n')\n    .trim()\n}\n\n/** One content block (structural subset of DSH's ContentBlock). */\nexport interface ContentBlockLike {\n  type: string\n  text?: string\n}\n\n/** Structural mirror of the DSH subagent seam. */\nexport interface SubagentsLike {\n  start?(name: string, request: {\n    label?: string\n    prompt?: readonly ContentBlockLike[]\n    parent?: unknown\n    signal?: unknown\n    agentOptions?: { provider?: string; model?: string; maxTokens?: number }\n    outputSchema?: { type: string; properties?: Record<string, unknown>; required?: string[] }\n  }): Promise<{\n    result: Promise<{ output?: readonly ContentBlockLike[]; stopReason?: string; structured?: unknown }>\n    dispose(): Promise<void>\n  }>\n}\n\n/** Structural mirror of the DSH tools registration contract. */\nexport interface ToolsService {\n  register(def: { name: string } & Record<string, unknown>): () => void\n}\n\nexport function apply(ctx: Context, config: Config = {}) {\n  ctx.effect(() => {\n    const tools = ctx.get('tools') as ToolsService\n    const subagents = ctx.get('subagents') as SubagentsLike | undefined\n    const disposers: (() => void)[] = []\n\n    disposers.push(tools.register({\n      name: 'tower',\n      description: 'Dispatch multiple instructions to a team of workers that iterate the repo concurrently, with conflict coordination and a reviewer pass.',\n      parameters: {\n        type: 'object',\n        properties: {\n          instructions: {\n            type: 'array',\n            items: { type: 'string' },\n            description: 'The list of instructions to dispatch (one worker per instruction).',\n          },\n          label: { type: 'string', description: 'Optional run label.' },\n        },\n        required: ['instructions'],\n      },\n      output: {\n        schema: {\n          type: 'object',\n          properties: {\n            plan: { type: 'array', items: { type: 'string' } },\n            workers: {\n              type: 'array',\n              items: {\n                type: 'object',\n                properties: {\n                  instruction: { type: 'string' },\n                  summary: { type: 'string' },\n                  stopReason: { type: 'string' },\n                },\n                required: ['instruction', 'summary', 'stopReason'],\n              },\n            },\n            review: { type: 'string' },\n            cleanup: { type: 'array', items: { type: 'string' } },\n          },\n          required: ['plan', 'workers', 'review', 'cleanup'],\n        },\n        render: (_args: unknown, value: unknown) => {\n          const v = value as TowerResult\n          const workerLines = v.workers.map((w, i) => `W${i + 1}: ${w.summary || `(${w.stopReason})`}`).join('\\n')\n          return [{\n            type: 'text',\n            text: `Tower run complete.\\n\\n## Workers\\n${workerLines || '(none)'}\\n\\n## Review\\n${v.review || '(no review)'}`,\n          }]\n        },\n      },\n      async execute(args: unknown, exec?: { agent?: unknown; signal?: unknown }): Promise<TowerResult> {\n        const { instructions, label } = args as { instructions?: string[]; label?: string }\n        if (!Array.isArray(instructions) || instructions.length === 0) {\n          throw new Error('tower: instructions must be a non-empty array')\n        }\n        const plan = instructions.map(s => String(s))\n        const maxWorkers = clamp(config.maxWorkers ?? 8, 1, 16)\n        const provider = config.provider ?? 'spawn'\n        const brief = buildTeamBrief(plan)\n\n        // Degrade gracefully without the subagent seam or a parent agent.\n        if (!subagents?.start || !exec?.agent) {\n          return {\n            plan,\n            workers: plan.map(instruction => ({\n              instruction,\n              summary: '(tower unavailable: no subagent seam or no agent context)',\n              stopReason: 'unavailable',\n            })),\n            review: '(tower unavailable)',\n            cleanup: [],\n          }\n        }\n\n        // 1) Workers, one per instruction, in parallel (bounded by maxWorkers).\n        const workerResults: TowerWorkerResult[] = []\n        for (let i = 0; i < plan.length; i += maxWorkers) {\n          const batch = plan.slice(i, i + maxWorkers)\n          const settled = await Promise.all(batch.map(async (instruction, j) => {\n            const index = i + j\n            const run = await subagents.start!(provider, {\n              label: label ? `${label}/W${index + 1}` : `tower/W${index + 1}`,\n              prompt: [{ type: 'text', text: buildWorkerPrompt(brief, instruction, index) }],\n              parent: exec.agent,\n              signal: exec.signal,\n              ...(config.secondaryModel ? { agentOptions: config.secondaryModel } : {}),\n              ...(config.outputSchema ? { outputSchema: config.outputSchema } : {}),\n            })\n            try {\n              const result = await run.result\n              return {\n                instruction,\n                summary: extractText(result.output),\n                stopReason: result.stopReason ?? 'completed',\n                ...(result.structured !== undefined ? { structured: result.structured } : {}),\n              }\n            } finally {\n              await run.dispose()\n            }\n          }))\n          workerResults.push(...settled)\n        }\n\n        // 2) Reviewer (primary model) re-reads the workers' outputs.\n        let review = ''\n        if (config.review !== false && subagents.start) {\n          try {\n            const run = await subagents.start(provider, {\n              label: label ? `${label}/review` : 'tower/review',\n              prompt: [{ type: 'text', text: buildReviewerPrompt(brief, workerResults) }],\n              parent: exec.agent,\n              signal: exec.signal,\n            })\n            try {\n              const result = await run.result\n              review = extractText(result.output)\n            } finally {\n              await run.dispose()\n            }\n          } catch {\n            review = '(reviewer unavailable)'\n          }\n        }\n\n        // 3) Revisit (optional): re-dispatch workers once more with the review feedback.\n        let finalWorkers = workerResults\n        if (config.revisit === true && review !== '' && review !== '(reviewer unavailable)' && subagents.start) {\n          const revisited: TowerWorkerResult[] = []\n          for (let i = 0; i < plan.length; i += maxWorkers) {\n            const batch = plan.slice(i, i + maxWorkers)\n            const settled = await Promise.all(batch.map(async (instruction, j) => {\n              const index = i + j\n              const run = await subagents.start!(provider, {\n                label: label ? `${label}/W${index + 1}/revisit` : `tower/W${index + 1}/revisit`,\n                prompt: [{ type: 'text', text: buildRevisitPrompt(brief, instruction, index, review) }],\n                parent: exec.agent,\n                signal: exec.signal,\n                ...(config.secondaryModel ? { agentOptions: config.secondaryModel } : {}),\n                ...(config.outputSchema ? { outputSchema: config.outputSchema } : {}),\n              })\n              try {\n                const result = await run.result\n                return {\n                  instruction,\n                  summary: extractText(result.output),\n                  stopReason: result.stopReason ?? 'completed',\n                  ...(result.structured !== undefined ? { structured: result.structured } : {}),\n                }\n              } finally {\n                await run.dispose()\n              }\n            }))\n            revisited.push(...settled)\n          }\n          finalWorkers = revisited\n        }\n\n        return { plan, workers: finalWorkers, review, cleanup: parseCleanup(review) }\n      },\n    }))\n\n    return () => {\n      for (const dispose of disposers.reverse()) dispose()\n    }\n  })\n}\n"
    },
